"use client";

import { useEffect, useRef, useState } from "react";

type ADHDHelperProps = {
  chapterNumber: number;
};

type PdfPageEventDetail = {
  pageNumber: number;
};

type VideoStateEventDetail = {
  playerId: string;
  playing: boolean;
};

const PAGE_IDLE_THRESHOLD_SECONDS = 35;
const TICK_MS = 1000;

function formatDuration(totalSeconds: number) {
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) return `${hours}h ${minutes}m ${seconds}s`;
  if (minutes > 0) return `${minutes}m ${seconds}s`;
  return `${seconds}s`;
}

export default function ADHDHelper({ chapterNumber }: ADHDHelperProps) {
  const [enabled, setEnabled] = useState(false);
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const [currentPage, setCurrentPage] = useState<number | null>(null);
  const [pageIdleSeconds, setPageIdleSeconds] = useState(0);
  const [videoPlaying, setVideoPlaying] = useState(false);
  const playingVideosRef = useRef<Set<string>>(new Set());
  const nudgedPageRef = useRef<number | null>(null);
  const [showNudge, setShowNudge] = useState(false);
  const lastStoredSecondRef = useRef(0);

  useEffect(() => {
    try {
      const saved = window.localStorage.getItem(`adhd-helper-enabled`);
      setEnabled(saved === "true");
    } catch {
      // localStorage can be unavailable in privacy-restricted browsers.
    }
  }, []);

  useEffect(() => {
    setElapsedSeconds(0);
    setCurrentPage(null);
    setPageIdleSeconds(0);
    setShowNudge(false);
    playingVideosRef.current.clear();
    nudgedPageRef.current = null;
    setVideoPlaying(false);

    try {
      const saved = Number(
        window.localStorage.getItem(`chapter-${chapterNumber}-time`) ?? "0"
      );
      if (Number.isFinite(saved) && saved >= 0) setElapsedSeconds(saved);
    } catch {
      // Ignore storage failures.
    }
  }, [chapterNumber]);

  useEffect(() => {
    const onPage = (event: Event) => {
      const detail = (event as CustomEvent<PdfPageEventDetail>).detail;
      if (!detail?.pageNumber) return;
      setCurrentPage(detail.pageNumber);
      setPageIdleSeconds(0);
      setShowNudge(false);
      nudgedPageRef.current = null;
    };

    const onVideo = (event: Event) => {
      const detail = (event as CustomEvent<VideoStateEventDetail & { playerId: string }>).detail;
      if (!detail?.playerId) return;

      if (detail.playing) {
        playingVideosRef.current.add(detail.playerId);
        setPageIdleSeconds(0);
        setShowNudge(false);
        nudgedPageRef.current = null;
      } else {
        playingVideosRef.current.delete(detail.playerId);
      }

      setVideoPlaying(playingVideosRef.current.size > 0);
    };

    window.addEventListener("pdf-page-visible", onPage);
    window.addEventListener("youtube-play-state", onVideo);

    return () => {
      window.removeEventListener("pdf-page-visible", onPage);
      window.removeEventListener("youtube-play-state", onVideo);
    };
  }, []);

  useEffect(() => {
    if (!enabled) return;

    let lastTick = Date.now();
    let active = !document.hidden;

    const onVisibilityChange = () => {
      active = !document.hidden;
      lastTick = Date.now();
    };

    const timer = window.setInterval(() => {
      const now = Date.now();
      const delta = Math.max(0, Math.min(5, Math.round((now - lastTick) / 1000)));
      lastTick = now;

      if (!active || delta === 0) return;

      setElapsedSeconds((value) => {
        const next = value + delta;
        if (next - lastStoredSecondRef.current >= 5) {
          lastStoredSecondRef.current = next;
          try {
            window.localStorage.setItem(
              `chapter-${chapterNumber}-time`,
              String(next)
            );
          } catch {
            // Ignore storage failures.
          }
        }
        return next;
      });

      if (!videoPlaying && currentPage !== null) {
        setPageIdleSeconds((value) => value + delta);
      }
    }, TICK_MS);

    document.addEventListener("visibilitychange", onVisibilityChange);

    return () => {
      window.clearInterval(timer);
      document.removeEventListener("visibilitychange", onVisibilityChange);
    };
  }, [chapterNumber, currentPage, enabled, videoPlaying]);

  useEffect(() => {
    if (!enabled || videoPlaying || currentPage === null) {
      setShowNudge(false);
      return;
    }

    if (pageIdleSeconds >= PAGE_IDLE_THRESHOLD_SECONDS && nudgedPageRef.current !== currentPage) {
      nudgedPageRef.current = currentPage;
      setShowNudge(true);
    }
  }, [currentPage, enabled, pageIdleSeconds, videoPlaying]);

  const toggle = () => {
    setEnabled((value) => {
      const next = !value;
      try {
        window.localStorage.setItem("adhd-helper-enabled", String(next));
      } catch {
        // Ignore storage failures.
      }
      if (!next) setShowNudge(false);
      return next;
    });
  };

  return (
    <>
      <div className="fixed bottom-5 right-5 z-[100]">
        <button
          type="button"
          onClick={toggle}
          aria-pressed={enabled}
          className={`rounded-full border px-4 py-3 text-sm font-semibold shadow-lg backdrop-blur transition ${
            enabled
              ? "border-[#7aa78f] bg-[#dbece3] text-[#173226]"
              : "border-[#dfe5e1] bg-white/95 text-[#46514b] hover:bg-[#f7f9f7]"
          }`}
        >
          🧠 ADHD Helper {enabled ? `On · ${formatDuration(elapsedSeconds)}` : "Off"}
        </button>
      </div>

      {enabled && showNudge && (
        <div className="fixed bottom-20 right-5 z-[99] w-[min(360px,calc(100vw-2rem))] rounded-2xl border border-[#c8d9cf] bg-white p-5 shadow-2xl">
          <div className="flex items-start justify-between gap-4">
            <div>
              <p className="text-xs font-bold uppercase tracking-[0.16em] text-[#68736d]">
                ADHD Helper
              </p>
              <h3 className="mt-1 text-lg font-bold">Time to refocus?</h3>
            </div>
            <button
              type="button"
              onClick={() => setShowNudge(false)}
              className="rounded-lg px-2 py-1 text-sm text-[#68736d] hover:bg-[#f1f4f2]"
              aria-label="Dismiss focus reminder"
            >
              ×
            </button>
          </div>
          <p className="mt-3 text-sm leading-6 text-[#46514b]">
            You have been on this page for {pageIdleSeconds}s without a video playing.
            Take a breath, refocus, and keep going.
          </p>
          <div className="mt-4 rounded-xl bg-[#f1f4f2] px-4 py-3 text-sm">
            <div className="flex items-center justify-between">
              <span className="text-[#68736d]">Chapter time</span>
              <strong>{formatDuration(elapsedSeconds)}</strong>
            </div>
            <div className="mt-1 flex items-center justify-between">
              <span className="text-[#68736d]">Current page</span>
              <strong>{currentPage ?? "—"}</strong>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
