"use client";

import { useEffect, useId, useRef } from "react";

type YouTubePlayerProps = {
  url: string;
  title?: string;
};

function embed(url: string) {
  if (!url) return "";

  try {
    const u = new URL(url);
    let id = "";

    if (u.hostname.includes("youtu.be")) {
      id = u.pathname.split("/").filter(Boolean)[0] ?? "";
    } else if (u.hostname.includes("youtube.com")) {
      id = u.searchParams.get("v") ?? "";
      if (!id && u.pathname.startsWith("/embed/")) {
        id = u.pathname.split("/").filter(Boolean)[1] ?? "";
      }
    }

    return id
      ? `https://www.youtube.com/embed/${id}?enablejsapi=1&rel=0&playsinline=1`
      : "";
  } catch {
    return "";
  }
}

export default function YouTubePlayer({ url, title = "YouTube video" }: YouTubePlayerProps) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerId = useId();
  const src = embed(url);

  useEffect(() => {
    if (!src) return;

    const postPauseState = (event: MessageEvent) => {
      if (event.source !== iframeRef.current?.contentWindow) return;
      if (!event.data || typeof event.data !== "string") return;

      try {
        const payload = JSON.parse(event.data);
        if (payload?.event !== "onStateChange") return;

        const state = Number(payload.info);
        const playing = state === 1;
        window.dispatchEvent(
          new CustomEvent("youtube-play-state", {
            detail: { playerId, playing },
          })
        );
      } catch {
        // Ignore unrelated postMessage events.
      }
    };

    const timer = window.setTimeout(() => {
      iframeRef.current?.contentWindow?.postMessage(
        JSON.stringify({ event: "listening", id: 1, channel: "widget" }),
        "*"
      );
      iframeRef.current?.contentWindow?.postMessage(
        JSON.stringify({ event: "command", func: "addEventListener", args: ["onStateChange"] }),
        "*"
      );
    }, 500);

    window.addEventListener("message", postPauseState);

    return () => {
      window.clearTimeout(timer);
      window.removeEventListener("message", postPauseState);
    };
  }, [playerId, src]);

  if (!src) {
    return (
      <div className="flex aspect-video items-center justify-center bg-[#eef2ef] p-6 text-center">
        <div>
          <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-[#B2D3C2] text-xl">
            ▶
          </div>
          <p className="font-semibold">{title}</p>
          <p className="mt-1 text-sm text-[#68736d]">
            Add the YouTube URL in the chapter or review data file.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="overflow-hidden rounded-2xl border border-[#dfe5e1] bg-white shadow-sm">
      <iframe
        ref={iframeRef}
        className="aspect-video w-full"
        src={src}
        title={title}
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowFullScreen
      />
    </div>
  );
}
