"use client";

import { useEffect, useRef, useState } from "react";

const PDFJS_VERSION = "3.11.174";
const PDFJS_SRC = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${PDFJS_VERSION}/pdf.min.js`;
const PDFJS_WORKER = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${PDFJS_VERSION}/pdf.worker.min.js`;

type PdfJsLib = {
  GlobalWorkerOptions: { workerSrc: string };
  getDocument: (src: string | { url: string }) => {
    promise: Promise<{
      numPages: number;
      getPage: (pageNumber: number) => Promise<{
        getViewport: (args: { scale: number }) => { width: number; height: number };
        render: (args: { canvasContext: CanvasRenderingContext2D; viewport: { width: number; height: number } }) => { promise: Promise<void> };
      }>;
    }>;
  };
};

declare global {
  interface Window {
    pdfjsLib?: PdfJsLib;
  }
}

let pdfJsPromise: Promise<PdfJsLib> | null = null;

function loadPdfJs() {
  if (typeof window === "undefined") {
    return Promise.reject(new Error("PDF.js can only load in the browser."));
  }

  if (window.pdfjsLib) {
    return Promise.resolve(window.pdfjsLib);
  }

  if (pdfJsPromise) return pdfJsPromise;

  pdfJsPromise = new Promise<PdfJsLib>((resolve, reject) => {
    const existing = document.querySelector<HTMLScriptElement>(
      'script[data-pdfjs="true"]'
    );

    if (existing) {
      existing.addEventListener("load", () => {
        if (window.pdfjsLib) resolve(window.pdfjsLib);
        else reject(new Error("PDF.js loaded but pdfjsLib was not found."));
      });
      existing.addEventListener("error", () => reject(new Error("Failed to load PDF.js.")));
      return;
    }

    const script = document.createElement("script");
    script.src = PDFJS_SRC;
    script.async = true;
    script.dataset.pdfjs = "true";
    script.onload = () => {
      if (window.pdfjsLib) resolve(window.pdfjsLib);
      else reject(new Error("PDF.js loaded but pdfjsLib was not found."));
    };
    script.onerror = () => reject(new Error("Failed to load PDF.js from CDN."));
    document.head.appendChild(script);
  });

  return pdfJsPromise;
}

export default function PdfBook({
  startPage,
  endPage,
}: {
  startPage: number;
  endPage: number;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(780);
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading");
  const [error, setError] = useState("");

  useEffect(() => {
    const element = containerRef.current;
    if (!element) return;

    const updateWidth = () => {
      setWidth(Math.max(280, Math.min(780, element.clientWidth - 32)));
    };

    updateWidth();
    const observer = new ResizeObserver(updateWidth);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    let cancelled = false;

    async function renderPdf() {
      const container = containerRef.current;
      if (!container) return;

      setStatus("loading");
      setError("");

      try {
        const pdfjs = await loadPdfJs();
        if (cancelled) return;

        pdfjs.GlobalWorkerOptions.workerSrc = PDFJS_WORKER;

        const pdf = await pdfjs.getDocument({
          url: `${process.env.NEXT_PUBLIC_BASE_PATH}/Calculus.pdf`,
        }).promise;
        if (cancelled) return;

        const first = Math.max(1, Math.min(startPage, pdf.numPages));
        const last = Math.max(first, Math.min(endPage, pdf.numPages));

        container.querySelectorAll(".pdf-canvas-page").forEach((node) => node.remove());

        for (let pageNumber = first; pageNumber <= last; pageNumber += 1) {
          if (cancelled) return;

          const page = await pdf.getPage(pageNumber);
          const unscaled = page.getViewport({ scale: 1 });
          const scale = width / unscaled.width;
          const viewport = page.getViewport({ scale });

          const wrapper = document.createElement("div");
          wrapper.className =
            "pdf-canvas-page mb-6 overflow-hidden rounded-xl border border-[#dfe5e1] bg-white shadow-sm";
          wrapper.dataset.page = String(pageNumber);

          const label = document.createElement("div");
          label.className =
            "border-b border-[#eef1ef] px-4 py-2 text-xs font-semibold text-[#68736d]";
          label.textContent = `Page ${pageNumber}`;

          const canvas = document.createElement("canvas");
          canvas.className = "block w-full";
          canvas.width = Math.ceil(viewport.width);
          canvas.height = Math.ceil(viewport.height);

          wrapper.appendChild(label);
          wrapper.appendChild(canvas);
          container.appendChild(wrapper);

          const context = canvas.getContext("2d");
          if (!context) throw new Error(`Could not create canvas for page ${pageNumber}.`);

          await page.render({ canvasContext: context, viewport }).promise;
        }

        if (!cancelled) setStatus("ready");
      } catch (err) {
        if (cancelled) return;
        setStatus("error");
        setError(err instanceof Error ? err.message : "Unable to render the PDF.");
      }
    }

    renderPdf();
    return () => {
      cancelled = true;
    };
  }, [startPage, endPage, width]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const getVisiblePage = () => {
      const pages = Array.from(
        container.querySelectorAll<HTMLElement>(".pdf-canvas-page[data-page]")
      );
      if (!pages.length) return;

      const viewportCenter = window.innerHeight / 2;
      let bestPage: HTMLElement | null = null;
      let bestDistance = Number.POSITIVE_INFINITY;

      for (const page of pages) {
        const rect = page.getBoundingClientRect();
        const center = rect.top + rect.height / 2;
        const distance = Math.abs(center - viewportCenter);
        if (distance < bestDistance) {
          bestDistance = distance;
          bestPage = page;
        }
      }

      const pageNumber = Number(bestPage?.dataset.page);
      if (pageNumber) {
        window.dispatchEvent(
          new CustomEvent("pdf-page-visible", { detail: { pageNumber } })
        );
      }
    };

    const observer = new IntersectionObserver(
      () => getVisiblePage(),
      { threshold: [0, 0.25, 0.5, 0.75, 1] }
    );

    container
      .querySelectorAll<HTMLElement>(".pdf-canvas-page")
      .forEach((node) => observer.observe(node));

    const onScroll = () => getVisiblePage();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    getVisiblePage();

    return () => {
      observer.disconnect();
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, [status]);

  return (
    <div ref={containerRef} className="textbook-shell">
      {status === "loading" && (
        <div className="rounded-xl bg-white p-10 text-center text-[#68736d]">
          Loading textbook…
        </div>
      )}

      {status === "error" && (
        <div className="rounded-xl bg-white p-10 text-center">
          <p className="font-semibold">Could not load the textbook.</p>
          <p className="mt-2 text-sm text-[#68736d]">
            Make sure the PDF is available at <code>public/Calculus.pdf</code>.
          </p>
          <p className="mt-2 break-words text-xs text-[#9aa49f]">{error}</p>
        </div>
      )}
    </div>
  );
}
